// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MONEY_BOX} from "../src/MONEY_BOX.sol";

contract InvMutTest is Test {
    MONEY_BOX c;
    function setUp() public { c = new MONEY_BOX(); }
    function testFuzz_property(uint256 newMin) public {
        newMin = bound(newMin, 0, type(uint256).max);

        c.SetMinSum(1);
        c.Initialized();

        bool ok;
        try c.SetMinSum(newMin) {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue( (ok == false) || (c.MinSum() == 1) );
    }
}
